      const trajectory=svgEl('path',{d:'M'+points.map(p=>p.join(',')).join(' L'),fill:'none',stroke:'#b83e4c','stroke-width':4,'stroke-linecap':'round','stroke-linejoin':'round'});svg.append(trajectory);
