    workspace.prepend(head);E('#animRange').max=lesson.frames.length-1;E('#animLessonInfo').textContent=`第${id}题 · ${lesson.frames.length}步`;E('#animTimelineLabel').textContent=`查看全部${lesson.frames.length}个动画步骤`;paint(false);
