  let printIndex=-1;window.addEventListener('beforeprint',()=>{if(!panel.isConnected)return;printIndex=index;stop();index=-1;paint(false)});window.addEventListener('afterprint',()=>{if(!panel.isConnected)return;index=printIndex;paint(false)});
